{
  "findings": [
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "A parent reports that the developer collects personal data and may retain it for internal uses.",
      "stance": "neutral",
      "quote": "We may store or process your Personal Data outside of the country where we collect the information or the country in which you reside. Our primary place of business is in the United States."
    },
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "A parent reports that the developer can delete personal data upon request, subject to exceptions.",
      "stance": "mitigation",
      "quote": "You have the right to request deletion of your Personal Data. If you choose to have your Personal Data removed from the Services, we will carry out your request within 30 days of verification, subject to extension, and we will only retain minimal Personal Data to document your request and the actions we took to carry out your request."
    },
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "A parent reports that the developer may retain data for internal uses that are reasonably aligned with user expectations.",
      "stance": "neutral",
      "quote": "enable solely internal uses that are reasonably aligned with user expectations based on your relationship with us and compatible with the context in which you provided the Personal Data."
    },
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "A parent reports that the developer may share personal data with third parties for business purposes.",
      "stance": "risk",
      "quote": "the categories of third parties with whom we disclose that Personal Data"
    },
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "A parent reports that the developer may retain data to comply with legal obligations.",
      "stance": "neutral",
      "quote": "comply with a legal obligation."
    }
  ]
}
